INSERT INTO service_subcategories (id, category_id, slug, name_en, name_pt, name_es, sort_order)
SELECT 'sub-' || v.slug, c.id, v.slug, v.en, v.pt, v.es, 0
FROM v JOIN service_categories c ON c.slug = v.cat;
